/**
 * CategoryForm Component Tests
 *
 * Tests for category form validation, submission, and interaction.
 * This file tests both new category creation and category editing flows,
 * including validation, error handling, slug generation, and form submission.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import type { Category } from '@/types/database'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
import CategoriesPage from '../page'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('CategoryForm', () => {
  const mockOrganizationId = 'test-org-id'

  // Helper function to create mock categories with correct type
  const createMockCategory = (overrides: Partial<Category> = {}): Category => {
    const now = new Date().toISOString()
    return {
      id: 'cat-' + Math.random().toString(36).substring(7),
      organization_id: 'org-test',
      name: 'Test Category',
      slug: 'test-category',
      sort_order: 0,
      parent_id: null,
      is_visible: true,
      created_at: now,
      ...overrides,
    }
  }

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('New Category Form', () => {
    describe('Form Rendering', () => {
      it('renders new category form with all fields', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        const fromMock = vi.fn(() => {
          return createMockQueryBuilder({ selectData: [] })
        })

        mockClient.from = fromMock as any

        function createMockQueryBuilder(config: any) {
          const queryBuilder = {
            select: vi.fn(() => queryBuilder),
            eq: vi.fn(() => queryBuilder),
            order: vi.fn(() => queryBuilder),
            then: vi.fn((callback) => {
              return Promise.resolve({
                data: config.selectData,
                error: null,
              }).then(callback)
            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<CategoriesPage />, {
          authContext: {
            organization: { id: mockOrganizationId } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Kategoriler')).toBeInTheDocument()
        })

        // Open the new category modal
        const newCategoryButton = screen.getByText('Yeni Kategori')
        await user.click(newCategoryButton)

        // Assert
        await waitFor(() => {
          expect(screen.getByLabelText('Kategori Adi')).toBeInTheDocument()
        })

        expect(screen.getByLabelText('URL Slug')).toBeInTheDocument()
        expect(screen.getByLabelText('Ust Kategori')).toBeInTheDocument()
        expect(screen.getByLabelText('Siralama')).toBeInTheDocument()
        expect(screen.getByLabelText('Menude goster')).toBeInTheDocument()
        expect(screen.getByText('Olustur')).toBeInTheDocument()
      })

      it('displays parent category options in dropdown', async () => {
