            }),
          }
          return queryBuilder
        }

        const user = userEvent.setup()

        // Act
        render(<CategoriesPage />, {
          authContext: {
            organization: { id: mockOrganizationId } as any,
          },
        })

        await waitFor(() => {
          expect(screen.getByText('Kategoriler')).toBeInTheDocument()
        })

        // Open the new category modal
        const newCategoryButton = screen.getByText('Yeni Kategori')
        await user.click(newCategoryButton)

        await waitFor(() => {
          expect(screen.getByLabelText('Kategori Adi')).toBeInTheDocument()
        })

        // Type name to auto-generate slug
        const nameInput = screen.getByLabelText('Kategori Adi')
        await user.type(nameInput, 'Ana Yemekler')

        await waitFor(() => {
          const slugInput = screen.getByLabelText('URL Slug') as HTMLInputElement
          expect(slugInput.value).toBe('ana-yemekler')
        })

        // Clear and manually set slug
        const slugInput = screen.getByLabelText('URL Slug')
        await user.clear(slugInput)
        await user.type(slugInput, 'custom-slug')

        // Type more in name field
        await user.type(nameInput, ' Test')

        // Assert - manual slug should not be overridden
        const slugInputFinal = screen.getByLabelText('URL Slug') as HTMLInputElement
        expect(slugInputFinal.value).toBe('custom-slug')
      })
    })

    describe('Form Submission', () => {
      it('successfully creates a new category with all fields', async () => {
        // Arrange
        const mockClient = createMockSupabaseClient()
        vi.mocked(createClient).mockReturnValue(mockClient as any)

        let capturedCategoryData: any = null

        const fromMock = vi.fn((table: string) => {
          if (table === 'categories') {
            return createCategoryQueryBuilder()
